export const MONUMENTS = JSON.parse("[{\"id\":\"n9743917663\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. А. Майорову\",\"x\":-2389,\"z\":-2692.1,\"subject\":\"Q109486789\",\"inscription\":\"С 1962 по 1986 год кафедру \\\"Вычислительной техники возглавлял Лауреат государственной премии СССР, Заслуженный деятель науки и техники РСФСР Доктор Технических наук Профессор Майоров Сергей Александрович. Ноябрь 1987\"},{\"id\":\"n481040120\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. П. Кадочникову\",\"x\":-1791.9,\"z\":-2715.6,\"subject\":\"Q384090\",\"inscription\":\"В этом доме с 1952 по 1988 год жил Павел Петрович Кадочников, Народный артист СССР, Герой Социалистического Труда\"},{\"id\":\"n1029463448\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"М. Горькому\",\"x\":-1757.5,\"z\":-2711.3,\"subject\":\"Q12706\"},{\"id\":\"n7276054650\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"К. М. Сергееву\",\"x\":-1763.9,\"z\":-2746.6,\"subject\":\"Q1352511\",\"inscription\":\"В этом доме с 1951 жил великий танцовщик и балетмейстер, первый президент Академии русского балета Константин Михайлович Сергеев\"},{\"id\":\"n9020896407\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. М. Горькому\",\"x\":-1836.4,\"z\":-2721.7,\"subject\":\"Q12706\",\"inscription\":\"В этом доме жил с 1914 г. по 1921 г. Алексей Максимович Горький\"},{\"id\":\"n8777431968\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Б. М. Кустодиеву\",\"x\":-2780.1,\"z\":-2688.7,\"subject\":\"Q313275\",\"inscription\":\"В этом доме с 1915 г. по 1927 г. жил и работал выдающийся русский художник академик живописи Борис Михайлович Кустодиев\"},{\"id\":\"n10011300660\",\"kind\":\"artwork\",\"sub\":\"graffiti\",\"x\":-2700.3,\"z\":-2702.6}]");
